import{z as i,x as T,o as l,c as d,q as r,j as s,D as e,d as E,s as o,S as A,b as t}from"./chunks/framework.C8m1ZpeB.js";const k=JSON.parse('{"title":"TTT 测试时训练层","description":"","frontmatter":{"title":"TTT 测试时训练层","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ttt-layers.md","filePath":"llm/ttt-layers.md","lastUpdated":1791413859000}'),p={name:"llm/ttt-layers.md"};function B(_,a,m,D,h,u){const n=T("Mermaid");return l(),d("div",null,[a[2]||(a[2]=r('<h1 id="ttt-测试时训练层" tabindex="-1">TTT 测试时训练层 <a class="header-anchor" href="#ttt-测试时训练层" aria-label="Permalink to &quot;TTT 测试时训练层&quot;">​</a></h1><div class="epigraph"><p>把隐状态当成一个小模型的权重，每个 token 对自监督损失做一步梯度下降；推理时这条更新仍然发生。</p><footer>—— Sun et al., Learning to (Learn at Test Time): RNNs with Expressive Hidden States, 2024</footer></div><p><a href="/llm/delta-rule-memory">上一课</a>的擦除-写入是固定公式。若把「让 \\(Sk\\) 接近 \\(v\\)」看成损失 \\(\\ell(W;x_t)\\)，则更新 \\(W\\leftarrow W-\\eta\\nabla_W\\ell\\) 就是一步测试时训练（Test-Time Training, TTT）。本课把线性 RNN 的状态重新解释为<strong>内环权重</strong>，外环仍是普通反向传播训投影与学习率。后课长卷积不再维护这种可学习状态，先把「测试时还在学」钉死。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>固定扫描规则无论门控还是 delta，表达力被更新族锁死。想要更强的内环（例如小型 MLP 当记忆，而不只是线性映射 \\(S\\)），就需要一个原则来导出更新，而不是每次手写 rank-1 公式。缺口是：<strong>规定内环模型与自监督损失，用梯度定义状态转移</strong>，使训练与推理都执行同一内环。</p><p>这与部署时用测试集微调整网不是一件事。TTT 层的内环只动那一小份状态权重，外环参数冻结于推理，且损失来自当前序列的 token 自身（如重建 \\(x_t\\) 或预测邻域），不来自标签。</p><p><span class="marginnote">术语翻译：这里的「测试时」不是指上线后拿用户数据微调大模型，而是指前向传播内部就在做「学习」这个动作——每个 token 触发一次小权重更新。整网主权重从头到尾冻结，用户数据也不会写进任何检查点。</span></p><p><span class="marginnote">外环梯度要穿过内环的梯度步，实现上是高阶导数或展开后的反传。步数一多，这就是 unrolled 优化，贵且脆。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>内环模型 \\(f_W\\)，例如线性 \\(f_W(k)=Wk\\)，或两层 MLP。每个时间步构造损失，如 \\(\\|f_W(k_t)-v_t\\|^2\\)。一步（或少量步）SGD / 带动量的更新得到 \\(W_t\\)，输出 \\(y_t=f_{W_t}(q_t)\\)。Sun 等人比较线性与 MLP 内环：MLP 更表达，状态是 MLP 的权重向量，体积更大。</p><p><span class="marginnote">数字实例：线性内环的 \\(W\\) 是 \\(d\\times d\\) 矩阵，\\(d=64\\) 时状态就是 4096 个数，半精度约 8 KB；换成 MLP 内环，权重数按宽度平方涨，状态体积、显存和每步更新开销一起涨。所以评测必须报「内环类型与状态体积」——同样是 TTT，账单可以差一个量级。</span></p><p>并行化：线性内环加平方损失时，更新常能写成与 delta 类似的形式，可扫描。MLP 内环逐步成分更重，硬件感知更难。课序默认先理解线性 TTT 与 delta 的亲缘，再承认 MLP TTT 是表达力换速度。</p><h3 id="内外环分工" tabindex="-1">内外环分工 <a class="header-anchor" href="#内外环分工" aria-label="Permalink to &quot;内外环分工&quot;">​</a></h3><p>外环学：如何把 \\(x\\) 编成 \\(q,k,v\\)、内环学习率、初始化 \\(W_0\\)。内环学：当前序列上的那份 \\(W\\)。换一篇文档，\\(W\\) 重置，这是与普通层权重的差别——普通层跨文档共享，TTT 状态按序列重建。</p>',14)),(l(),s(A,null,{default:e(()=>[o(n,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E8%BE%93%E5%85%A5%E5%BA%8F%E5%88%97%22%5D%20--%3E%20ENC%5B%22%E5%A4%96%E7%8E%AF%E5%AD%A6%EF%BC%9A%E6%8A%8A%20x%20%E7%BC%96%E6%88%90%20q%2Ck%2Cv%22%5D%0A%20%20ENC%20--%3E%20INIT%5B%22%E5%A4%96%E7%8E%AF%E5%AD%A6%EF%BC%9A%E5%AD%A6%E4%B9%A0%E7%8E%87%E4%B8%8E%E5%88%9D%E5%A7%8B%20W_0%22%5D%0A%20%20INIT%20--%3E%20INNER%5B%22%E5%86%85%E7%8E%AF%EF%BC%9A%E9%80%90%20token%20%E6%A2%AF%E5%BA%A6%E6%9B%B4%E6%96%B0%20W%22%5D%0A%20%20INNER%20--%3E%20Y%5B%22%E8%BE%93%E5%87%BA%20y_t%22%5D%0A%20%20Y%20--%3E%20LOSS%5B%22%E5%A4%96%E7%8E%AF%E4%BB%BB%E5%8A%A1%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20LOSS%20--%3E%20BPTT%5B%22%E5%8F%8D%E4%BC%A0%E7%A9%BF%E8%BF%87%E5%86%85%E7%8E%AF%E6%9B%B4%E6%96%B0%E6%AD%A5%22%5D%0A%20%20INNER%20-.-%3E%7C%22%E6%8D%A2%E6%96%87%E6%A1%A3%22%7C%20RESET%5B%22W%20%E9%87%8D%E7%BD%AE%EF%BC%8C%E4%B8%8D%E5%86%99%E5%85%A5%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>自监督损失把「记忆该满足的约束」说清楚：见到 \\((k,v)\\) 之后，再用 \\(k\\) 去读应得到 \\(v\\)。梯度步是满足约束的通用方法，delta 规则是它在线性平方损失下的近亲。MLP 内环让约束可以非线性，容量上升，也失去 SSD 那样干净的对偶。</p><p>长序列上每步都更新，\\(W\\) 可能过拟合最近 token 而忘早期约束——内环同样需要隐式遗忘（学习率、权重衰减、有限容量）。TTT 不是无限记忆，它是把遗忘交给优化动力学。</p><p><span class="marginnote">直觉类比：内环的 \\(W\\) 像一块尺寸固定的小白板，每读一个 token 就擦掉一些旧内容腾地方。遗忘多少由学习率和容量决定，而不是谁设计了「删除」；容量给得越大，忘得越慢，每步也越贵。</span></p><p><span class="marginnote">与「测试时在用户数据上微调整模型」的隐私与延迟模型完全不同。TTT 层不把用户数据写入外环检查点。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>MLP 内环的训练稳定性、吞吐、实现成熟度都弱于 Mamba / GLA。本课不是建议把主干注意力全部换成 TTT。它提供一条概念桥：线性状态更新 = 内环一步学习。评测应报内环类型与状态体积，只报「用了 TTT」无法复现。下一课长卷积把记忆放进滤波器系数，推理不再逐步改权重，内环消失。</p>',7)),(l(),s(A,null,{default:e(()=>[o(n,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20Xt%5B%22%E5%BD%93%E5%89%8D%20token%22%5D%20--%3E%20Loss%5B%22%E5%86%85%E7%8E%AF%E8%87%AA%E7%9B%91%E7%9D%A3%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20W%5B%22W_%7Bt-1%7D%22%5D%20--%3E%20Loss%0A%20%20Loss%20--%3E%20Grad%5B%22%E4%B8%80%E6%AD%A5%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20Grad%20--%3E%20Wt%5B%22W_t%22%5D%0A%20%20Q%5B%22q_t%22%5D%20--%3E%20Y%5B%22f_W(q)%22%5D%0A%20%20Wt%20--%3E%20Y%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t("h2",{id:"小结",tabindex:"-1"},[E("小结 "),t("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=t("ul",null,[t("li",null,"TTT 层把隐状态当小模型权重，每 token 对自监督损失做测试时梯度步。"),t("li",null,"线性平方损失下与 delta 规则近亲；MLP 内环更表达、更难并行。"),t("li",null,"外环学编码与学习率，内环权重按序列重置，不写入检查点。"),t("li",null,"有限容量加持续更新仍会忘；不是无损记忆。"),t("li",null,"出处：Sun et al., 2024。")],-1))])}const c=i(p,[["render",B]]);export{k as __pageData,c as default};
